import sys

def main():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return
    lines = [line.strip() for line in data]
    idx = 0

    def readline():
        nonlocal idx
        if idx < len(lines):
            line = lines[idx]
            idx += 1
            return line
        return ''

    def output(x):
        print(x)

    N = int(readline())

    for _ in range(N):
        x = int(readline())
        arr = list(map(int, readline().split()))

        result = 'YES'

        first = arr[x - 1]
        second = arr[first - 1] if first != 0 else 0

        if first == 0:
            result = 'NO'
        elif second == 0:
            result = 'NO'

        output(result)

if __name__ == "__main__":
    main()

