'use strict';

process.stdin.resume();
process.stdin.setEncoding('utf-8');

let inputString = '';
let currentLine = 0;

process.stdin.on('data', inputStdin => {
    inputString += inputStdin;
});

process.stdin.on('end', _ => {
    inputString = inputString.trim().split('\n').map(string => {
        return string.trim();
    });
    
    main();    
});

function readline() {
    return inputString[currentLine++];
}

function output(x) {
    if (typeof x !== 'string') {
        x = x.toString();
    }
    //process.stdout.write(x);   // without auto '\n' (newline)
    console.log(x);  // with auto '\n' (newline)
}

function main() {
    let N = readline();

    for (let test = 0; test < N; test++) {
        let x = Number(readline());
        let arr = readline().split(' ').map(Number);

        let result = 'YES';

        let first = arr[x - 1];
        let second = first ? arr[first - 1] : 0;

        if (first === 0) {
            result = 'NO';
        } else if (second === 0) {
            result = 'NO';
        }

        output(result);
    }
}
